/**
 * Action 07 Prompt Module for tx-4-imp-1 Agent
 * 
 * This module generates prompts for Action 7 of the tx-4-imp-1 agent workflow.
 * Action 7: 未提出メンバーリストを自動抽出して通知する
 * (Automatically extract and notify members who have not submitted reports)
 */

export const ACTION_07_PROMPT_VERSION = "1.0.0";

export interface Action07PromptInput {
  unsubmittedMembers: Array<{
    memberId: string;
    memberName: string;
    email: string;
    department: string;
    lastSubmissionDate?: string;
  }>;
  reportingDeadline: string;
  reportingPeriod: string;
  escalationThresholdDays?: number;
  notificationTemplate?: string;
}

export interface Action07PromptOutput {
  version: string;
  systemPrompt: string;
  userPrompt: string;
  context: {
    unsubmittedCount: number;
    escalationCount: number;
    notificationGroups: Array<{
      groupName: string;
      members: Array<{
        memberId: string;
        memberName: string;
        email: string;
        department: string;
        daysOverdue: number;
        priority: "high" | "medium" | "low";
      }>;
      recommendedAction: string;
    }>;
  };
}

export function buildAction07Prompt(
  input: Action07PromptInput
): Action07PromptOutput {
  const escalationThreshold = input.escalationThresholdDays ?? 1;
  
  // Calculate days overdue for each member
  const now = new Date();
  const deadline = new Date(input.reportingDeadline);
  
  const notificationGroups: Action07PromptOutput["context"]["notificationGroups"] = [];
  
  // Group 1: Escalation cases (significantly overdue)
  const escalationMembers = input.unsubmittedMembers
    .map((member) => {
      const lastSubmission = member.lastSubmissionDate
        ? new Date(member.lastSubmissionDate)
        : deadline;
      const daysOverdue = Math.floor(
        (now.getTime() - lastSubmission.getTime()) / (1000 * 60 * 60 * 24)
      );
      return {
        ...member,
        daysOverdue,
      };
    })
    .filter((member) => member.daysOverdue >= escalationThreshold)
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  if (escalationMembers.length > 0) {
    notificationGroups.push({
      groupName: "Escalation - Significantly Overdue",
      members: escalationMembers.map((member) => ({
        memberId: member.memberId,
        memberName: member.memberName,
        email: member.email,
        department: member.department,
        daysOverdue: member.daysOverdue,
        priority: "high" as const,
      })),
      recommendedAction:
        "Send immediate escalation notification to manager and member. Consider follow-up call.",
    });
  }

  // Group 2: Standard overdue (within escalation threshold)
  const standardOverdueMembers = input.unsubmittedMembers
    .map((member) => {
      const lastSubmission = member.lastSubmissionDate
        ? new Date(member.lastSubmissionDate)
        : deadline;
      const daysOverdue = Math.floor(
        (now.getTime() - lastSubmission.getTime()) / (1000 * 60 * 60 * 24)
      );
      return {
        ...member,
        daysOverdue,
      };
    })
    .filter((member) => member.daysOverdue > 0 && member.daysOverdue < escalationThreshold)
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  if (standardOverdueMembers.length > 0) {
    notificationGroups.push({
      groupName: "Standard Reminder - Overdue",
      members: standardOverdueMembers.map((member) => ({
        memberId: member.memberId,
        memberName: member.memberName,
        email: member.email,
        department: member.department,
        daysOverdue: member.daysOverdue,
        priority: "medium" as const,
      })),
      recommendedAction:
        "Send standard reminder notification with submission link and deadline.",
    });
  }

  // Group 3: Not yet due but approaching deadline
  const approachingDeadlineMembers = input.unsubmittedMembers
    .map((member) => {
      const lastSubmission = member.lastSubmissionDate
        ? new Date(member.lastSubmissionDate)
        : deadline;
      const daysOverdue = Math.floor(
        (now.getTime() - lastSubmission.getTime()) / (1000 * 60 * 60 * 24)
      );
      return {
        ...member,
        daysOverdue,
      };
    })
    .filter((member) => member.daysOverdue <= 0)
    .sort((a, b) => a.daysOverdue - b.daysOverdue);

  if (approachingDeadlineMembers.length > 0) {
    notificationGroups.push({
      groupName: "Advance Notice - Approaching Deadline",
      members: approachingDeadlineMembers.map((member) => ({
        memberId: member.memberId,
        memberName: member.memberName,
        email: member.email,
        department: member.department,
        daysOverdue: member.daysOverdue,
        priority: "low" as const,
      })),
      recommendedAction:
        "Send advance notice reminder with submission deadline and template.",
    });
  }

  const systemPrompt = `You are an AI assistant responsible for managing and notifying unsubmitted report members in a morning meeting management system.

Your role is to:
1. Analyze the list of members who have not submitted their daily reports
2. Categorize them by urgency level based on how overdue their submissions are
3. Generate appropriate notification messages for each category
4. Recommend escalation actions for significantly overdue cases
5. Ensure all notifications are professional, clear, and actionable

Guidelines:
- Prioritize escalation cases that are significantly overdue
- Provide specific, actionable next steps for each notification group
- Consider department and reporting relationships when recommending actions
- Maintain a balance between urgency and professionalism in messaging
- Track notification history to avoid duplicate or excessive reminders`;

  const userPrompt = `Please analyze the following unsubmitted report members and generate notification strategy:

Reporting Period: ${input.reportingPeriod}
Reporting Deadline: ${input.reportingDeadline}
Escalation Threshold: ${escalationThreshold} day(s)
Current Time: ${now.toISOString()}

Unsubmitted Members Count: ${input.unsubmittedMembers.length}

Members by Department:
${
  Array.from(
    new Map(
      input.unsubmittedMembers.map((m) => [
        m.department,
        (input.unsubmittedMembers.filter((x) => x.department === m.department) || []).length,
      ])
    ).entries()
  )
    .map(([dept, count]) => `- ${dept}: ${count} members`)
    .join("\n")
}

Notification Groups Analysis:
${notificationGroups
  .map(
    (group) => `
${group.groupName}:
  Count: ${group.members.length}
  Recommended Action: ${group.recommendedAction}
  Members:
${group.members.map((m) => `    - ${m.memberName} (${m.email}) - ${m.daysOverdue} days overdue`).join("\n")}
`
  )
  .join("\n")}

Please provide:
1. Summary of notification strategy by priority level
2. Specific notification messages for each group
3. Escalation recommendations for high-priority cases
4. Follow-up actions and timeline
5. Any patterns or concerns identified in the unsubmitted members`;

  return {
    version: ACTION_07_PROMPT_VERSION,
    systemPrompt,
    userPrompt,
    context: {
      unsubmittedCount: input.unsubmittedMembers.length,
      escalationCount: escalationMembers.length,
      notificationGroups,
    },
  };
}
